import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> Any:
    expected_width = 23

    try:
        records = list(csv.reader(
            io.StringIO(raw_csv.lstrip("\ufeff"), newline=""),
            delimiter=";",
            quotechar='"',
            doublequote=True,
            strict=False,
        ))
    except csv.Error:
        records = []

    records = [record for record in records if record]

    def header_score(record):
        return sum(
            1
            for value in record
            if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", value.strip())
        )

    candidates = [
        (index, record)
        for index, record in enumerate(records)
        if len(record) == expected_width
    ]

    if candidates:
        header_index, header = max(
            candidates,
            key=lambda item: (header_score(item[1]), -item[0]),
        )
    elif records:
        header_index, header = max(
            enumerate(records),
            key=lambda item: (header_score(item[1]), -item[0]),
        )
    else:
        return {"columns": [], "rows": []}

    columns = list(header)
    data_rows = [list(row) for row in records[header_index + 1:]]
    width = max([len(columns)] + [len(row) for row in data_rows])

    while len(columns) < width:
        columns.append(f"extra_{len(columns) + 1}")

    for row in data_rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": data_rows}
